defs.script:
(function(){
  function supportsManagedAudioStart(){
    try {
      var svgRoot = document.documentElement;
      var clickTimeline = document.getElementById('timeline-click');
      if (!svgRoot || !clickTimeline) return false;
      return typeof svgRoot.pauseAnimations === 'function' &&
        typeof svgRoot.unpauseAnimations === 'function' &&
        typeof clickTimeline.beginElement === 'function';
    } catch (e) {
      return false;
    }
  }
  function hideLegacyUi(){
    var legacyNotice = document.getElementById('legacy-autoplay-notice');
    if (legacyNotice) legacyNotice.style.display = 'none';
    var legacyPauseWarning = document.getElementById('legacy-pause-warning');
    if (legacyPauseWarning) legacyPauseWarning.style.display = 'none';
  }
  function setManagedUi(){
    var autoLayer = document.querySelector('.smil-autoplay-layer');
    var clickLayer = document.querySelector('.smil-onclick-layer');
    var autoGroup = document.querySelector('.smil-autoplay-trigger');
    var clickGroup = document.querySelector('.smil-onclick-trigger');
    if (autoLayer) autoLayer.style.display = 'none';
    if (clickLayer) clickLayer.style.display = 'inline';
    if (autoGroup) autoGroup.style.display = 'none';
    if (clickGroup) clickGroup.style.display = 'inline';
    hideLegacyUi();
  }
  function stripAutoplaySyncbase(expr){
    if (typeof expr !== 'string' || expr.indexOf('timeline-autoplay.') === -1) return expr;
    var parts = expr.split(';');
    var kept = [];
    for (var i = 0; i < parts.length; i++) {
      var token = parts[i].trim();
      if (!token) continue;
      if (token.indexOf('timeline-autoplay.begin') === 0) continue;
      if (token.indexOf('timeline-autoplay.repeat') === 0) continue;
      if (token.indexOf('timeline-autoplay.end') === 0) continue;
      kept.push(token);
    }
    return kept.join(';');
  }
  function stripManagedPlayEvents(expr){
    if (typeof expr !== 'string') return expr;
    var audioId = "aud";
    var smilAudioId = "aud";
    var blocked = {};
    if (audioId) blocked[audioId + '.play'] = true;
    if (smilAudioId) blocked[smilAudioId + '.play'] = true;
    var parts = expr.split(';');
    var kept = [];
    for (var i = 0; i < parts.length; i++) {
      var token = parts[i].trim();
      if (!token) continue;
      if (blocked[token]) continue;
      kept.push(token);
    }
    return kept.join(';');
  }
  function retargetToClickTimeline(){
    var autoplayTimeline = document.getElementById('timeline-autoplay');
    if (autoplayTimeline) {
      try { autoplayTimeline.setAttribute('begin', 'indefinite'); } catch (e) {}
      try { autoplayTimeline.setAttribute('repeatCount', '1'); } catch (e) {}
      try { autoplayTimeline.removeAttribute('restart'); } catch (e) {}
      try { if (typeof autoplayTimeline.endElement === 'function') autoplayTimeline.endElement(); } catch (e) {}
    }
    var sets = [];
    try {
      sets = document.querySelectorAll('set[begin*="timeline-autoplay"],set[end*="timeline-autoplay"]');
    } catch (e) {
      sets = [];
    }
    for (var i = 0; i < sets.length; i++) {
      var node = sets[i];
      var begin = node.getAttribute('begin');
      if (begin && begin.indexOf('timeline-autoplay.') !== -1) {
        var nextBegin = stripAutoplaySyncbase(begin);
        if (nextBegin) node.setAttribute('begin', nextBegin);
        else node.removeAttribute('begin');
      }
      var end = node.getAttribute('end');
      if (end && end.indexOf('timeline-autoplay.') !== -1) {
        var nextEnd = stripAutoplaySyncbase(end);
        if (nextEnd) node.setAttribute('end', nextEnd);
        else node.removeAttribute('end');
      }
    }
    var clickTimeline = document.getElementById('timeline-click');
    if (clickTimeline) {
      var clickBegin = clickTimeline.getAttribute('begin');
      var nextClickBegin = stripManagedPlayEvents(clickBegin);
      if (nextClickBegin) clickTimeline.setAttribute('begin', nextClickBegin);
    }
  }
  function resetFrameVisibility(){
    var frames = [];
    try {
      frames = document.querySelectorAll('#stage > g[id^="frame-"]');
    } catch (e) {
      frames = [];
    }
    for (var i = 0; i < frames.length; i++) {
      try { frames[i].setAttribute('visibility', 'hidden'); } catch (e) {}
    }
  }
  function startClickTimeline(){
    var clickTimeline = document.getElementById('timeline-click');
    if (!clickTimeline || typeof clickTimeline.beginElement !== 'function') return;
    try { clickTimeline.beginElement(); } catch (e) {}
  }
  function setTimeZero(svgRoot){
    try { if (svgRoot && typeof svgRoot.setCurrentTime === 'function') svgRoot.setCurrentTime(0); } catch (e) {}
  }
  function pauseIfPossible(svgRoot){
    try {
      if (svgRoot && typeof svgRoot.pauseAnimations === 'function') {
        svgRoot.pauseAnimations();
        return true;
      }
    } catch (e) {}
    return false;
  }
  function unpauseIfPossible(svgRoot){
    try {
      if (svgRoot && typeof svgRoot.unpauseAnimations === 'function') {
        svgRoot.unpauseAnimations();
      }
    } catch (e) {}
  }
  function forceFirefoxAutoplay(){
    var ua = (typeof navigator !== 'undefined' && navigator.userAgent) ? navigator.userAgent : '';
    if (ua.indexOf('Firefox/') === -1) return false;
    var svgRoot = document.documentElement;
    var autoplayTimeline = document.getElementById('timeline-autoplay');
    setTimeZero(svgRoot);
    unpauseIfPossible(svgRoot);
    try { if (autoplayTimeline && typeof autoplayTimeline.beginElement === 'function') autoplayTimeline.beginElement(); } catch (e) {}
    return true;
  }
  function shouldPreserveAutoplay(svgRoot, aud){
    var svgTime = 0;
    var audioTime = 0;
    var paused = true;
    try { paused = !!aud.paused; } catch (e) {}
    if (!paused) return true;
    try {
      if (svgRoot && typeof svgRoot.getCurrentTime === 'function') svgTime = svgRoot.getCurrentTime() || 0;
    } catch (e) {}
    try {
      if (aud && typeof aud.currentTime === 'number') audioTime = aud.currentTime || 0;
    } catch (e) {}
    return svgTime > 0.05 && audioTime > 0.05;
  }
  function init(){
    if (!supportsManagedAudioStart()) return;
    var svgRoot = document.documentElement;
    var aud = document.getElementById("aud");
    if (!svgRoot || !aud) return;
    var started = false;
    var preserveAutoplay = shouldPreserveAutoplay(svgRoot, aud);
    if (preserveAutoplay) {
      hideLegacyUi();
      unpauseIfPossible(svgRoot);
      started = true;
    } else {
      setManagedUi();
      retargetToClickTimeline();
      resetFrameVisibility();
      setTimeZero(svgRoot);
      pauseIfPossible(svgRoot);
    }
    function beginPlayback(){
      if (!started) {
        setTimeZero(svgRoot);
        startClickTimeline();
      }
      unpauseIfPossible(svgRoot);
      started = true;
    }
    try {
      aud.addEventListener('play', function(){
        beginPlayback();
      });
      aud.addEventListener('pause', function(){
        if (!started) return;
        pauseIfPossible(svgRoot);
      });
    } catch (e) {}
    try {
      if (!aud.paused) beginPlayback();
    } catch (e) {}
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
